  try {
    const buf = await res.arrayBuffer();
    info.bufType = Object.prototype.toString.call(buf);
    const u8 = new Uint8Array(buf);
    info.bytes = u8.length;
    info.head = Array.from(u8.slice(0, 8)).map(b => b.toString(16)).join(' ');
